from __future__ import annotations
from typing import Sequence

def success(q: Sequence[float], posterior: Sequence[float]) -> float:
    if len(q) != len(posterior) or abs(sum(q) - 1.0) > 1e-12 or min(q) < 0:
        raise ValueError("q must be a probability distribution of matching length")
    return sum(a * b for a, b in zip(q, posterior))

if __name__ == "__main__":
    p = [0.12, 0.08, 0.25, 0.10, 0.18, 0.09, 0.18]
    rules = {"MAP": [0, 0, 1, 0, 0, 0, 0],
             "3/5 mixture": [0, 0, .5, 0, .5, 0, 0],
             "uniform": [1 / 7] * 7}
    for name, q in rules.items():
        print(f"{name:12s}: {success(q, p):.6f}")

from __future__ import annotations
from fractions import Fraction

def scaling(n: int, k: int, c: Fraction = Fraction(1)) -> Fraction:
    if n == k:
        raise ValueError("undefined at n = k")
    return c * (1 - Fraction(k, n - k)) ** 2

if __name__ == "__main__":
    print("F(7,2;1) =", scaling(7, 2), "=", float(scaling(7, 2)))
    for k in range(1, 6):
        print(f"parity check k={k}: F({2*k},{k};1) = {scaling(2*k, k)}")

