from __future__ import annotations
from typing import Sequence

def audit_policy(q: Sequence[float], posterior: Sequence[float], tolerance: float = 1e-12) -> dict[str, float | bool]:
    if len(q) != len(posterior) or not q:
        raise ValueError("matching nonempty vectors required")
    if min(q) < 0 or abs(sum(q) - 1) > tolerance:
        raise ValueError("invalid randomized rule")
    achieved = sum(weight * value for weight, value in zip(q, posterior))
    optimum = max(posterior)
    return {"achieved": achieved, "optimum": optimum,
            "regret": optimum - achieved, "optimal": optimum - achieved <= tolerance}

from __future__ import annotations
from fractions import Fraction

def scaling_table(n_min: int, n_max: int, constant: Fraction = Fraction(1)) -> list[tuple[int, int, Fraction]]:
    if n_min < 2 or n_max < n_min:
        raise ValueError("require 2 <= n_min <= n_max")
    rows: list[tuple[int, int, Fraction]] = []
    for n in range(n_min, n_max + 1):
        for k in range(1, n):
            value = constant * (1 - Fraction(k, n - k)) ** 2
            rows.append((n, k, value))
    return rows

